// Local Tauri mobile plugin: the foreground service that keeps the WebView —
// and with it the acceptance rule — running while the app is in the background
// (`AcceptanceService.kt`).
//
// Wired in by `gen/android/settings.gradle` (`include(":edet-background")`) and
// `gen/android/app/build.gradle.kts` (`implementation(project(":edet-background"))`),
// both of which are TRACKED for that reason: `tauri android init` regenerates
// everything in `gen/android` that carries its AUTOGENERATED banner, and those
// two do not, so a regeneration that dropped them would take background mode
// with it and leave every gate green.
//
// **The service's manifest entry lives in THIS module, not in the app's.**
// `gen/android/app/src/main/AndroidManifest.xml` is regenerated, so a
// `<service>` written there is a declaration one `tauri android init` away
// from gone. A library manifest is merged into the app's by AGP, so the
// permissions and the service travel with the code that needs them.
plugins {
    id("com.android.library")
    id("org.jetbrains.kotlin.android")
}

android {
    namespace = "org.edet.client.background"
    // 34 for `FOREGROUND_SERVICE_TYPE_SPECIAL_USE`, which is where that
    // constant is defined; the runtime guards keep older devices on the
    // untyped `startForeground`.
    compileSdk = 34

    defaultConfig {
        // Notification channels (API 26) and typed foreground services (29)
        // are both guarded at runtime; 23 matches `edet-keystore`, so the two
        // committed modules agree on the floor.
        minSdk = 23
        consumerProguardFiles("consumer-rules.pro")
    }

    // Java 17, and it has to move together with `app/build.gradle.kts` — see
    // the same block in `edet-keystore/build.gradle.kts` for why a consumer at
    // a lower target cannot read a library at a higher one.
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    kotlinOptions {
        jvmTarget = "17"
    }
}

dependencies {
    implementation("androidx.core:core-ktx:1.12.0")
    // Provides app.tauri.plugin.{Plugin,Invoke,JSObject} and the
    // app.tauri.annotation.{TauriPlugin,Command} annotations every Tauri
    // Android plugin implements against.
    implementation(project(":tauri-android"))
}
